# ============================================================
#  COLUMN FINDER
# ============================================================
def _clean(s): return re.sub(r"[^a-z0-9 ]"," ",str(s).lower()).strip()
def _nodot(s):  return re.sub(r"[^a-z0-9]","",str(s).lower())

def _find_col(columns, field, kw_map):
    keywords  = kw_map.get(field, [field.lower()])
    lower_map = {c.lower().strip(): c for c in columns}
    clean_map = {_clean(c): c for c in columns}
    nodot_map = {_nodot(c): c for c in columns}
    for kw in keywords:
        if kw.lower() in lower_map: return lower_map[kw.lower()]
    for kw in keywords:
        if _clean(kw) in clean_map: return clean_map[_clean(kw)]
    for kw in keywords:
        kw_c = _clean(kw)
        for col_c, col_orig in clean_map.items():
            if kw_c and kw_c in col_c: return col_orig
    for kw in keywords:
        kw_c = _clean(kw)
        for col_c, col_orig in clean_map.items():
            if col_c and len(col_c) >= 3 and col_c in kw_c: return col_orig
    for kw in keywords:
        kw_nd = _nodot(kw)
        if kw_nd in nodot_map: return nodot_map[kw_nd]
        for col_nd, col_orig in nodot_map.items():
            if col_nd and len(col_nd) >= 3 and col_nd in kw_nd: return col_orig
    return None


# ============================================================
#  HEADER ROW FINDER
# ============================================================
def _find_header_row(all_rows, max_scan=20, col_keywords=None):
    if col_keywords is None:
        col_keywords = ["gstin","gst","invoice","bill","taxable","igst","cgst","sgst",
                        "date","voucher","supplier","vendor","party","value","amount"]
    best_idx = None; best_score = 0
    for i, row in enumerate(all_rows[:max_scan]):
        row_str  = " ".join(str(v).lower() for v in row if v is not None)
        score    = sum(1 for kw in col_keywords if kw in row_str)
        non_none = sum(1 for v in row if v is not None)
        if non_none >= 3:
            if score > best_score: best_score = score; best_idx = i
            elif best_idx is None: best_idx = i
    return best_idx if best_idx is not None else 0


# ============================================================
#  GSTR-2B LOADER
# ============================================================
def _load_b2b_sheet(file_obj, sheet_type="B2B"):
    file_obj.seek(0); raw = file_obj.read()
    # Try normal load first, then read_only fallback
    wb = None
    for _ro in [False, True]:
        try:
            wb = openpyxl.load_workbook(io.BytesIO(raw), read_only=_ro, data_only=True)
            break
        except Exception as _e:
            last_err = _e
    if wb is None:
        # Last resort: try xlrd / pandas
        try:
            xf = pd.ExcelFile(io.BytesIO(raw))
            # Can't use _load_b2b_sheet logic easily here, raise helpful error
            raise ValueError(
                f"GSTR-2B file could not be opened by the standard Excel reader.\n"
                f"Sheets found via fallback: {xf.sheet_names}\n"
                "Please open the file in Excel, Save As → Excel Workbook (.xlsx), and re-upload."
            )
        except ValueError: raise
        except Exception:
            raise ValueError(
                "GSTR-2B file is corrupted or not a valid Excel file.\n"
                "Please download fresh from the GST Portal and re-upload."
            )
    sheets = wb.sheetnames
    b2b_name = None
    if sheet_type == "CDNR":
        for s in sheets:
            if "cdnr" in s.lower() or "credit" in s.lower() or "debit" in s.lower() or "note" in s.lower():
                b2b_name = s; break
        if not b2b_name:
            # Maybe it doesn't exist, which is okay for CDNR
            return pd.DataFrame(), "", {}
    else:
        for s in sheets:
            if s.strip().upper() == "B2B": b2b_name = s; break
        if not b2b_name:
            for s in sheets:
                if re.match(r"^B2B", s.strip(), re.IGNORECASE) and "CDNR" not in s.upper():
                    b2b_name = s; break
        if not b2b_name:
            for s in sheets:
                if "b2b" in s.lower() and "cdnr" not in s.lower(): b2b_name = s; break
        if not b2b_name:
            raise ValueError(f"Could not find B2B sheet.\nSheets found: {sheets}")

    ws = wb[b2b_name]; all_rows = list(ws.iter_rows(values_only=True))
    if not all_rows:
        return pd.DataFrame(columns=list(B2B_COL_POS_FALLBACK.values())), b2b_name, {}

    det = {"method": "", "header_row": 0, "col_map": {}}
    gstr2b_kws = ["gstin","invoice","taxable","igst","cgst","sgst","supplier","trade","legal","integrated","central"]
    header_idx = _find_header_row(all_rows, max_scan=20, col_keywords=gstr2b_kws)
    det["header_row"] = header_idx + 1

    hr = [str(v).strip() if v is not None else "" for v in all_rows[header_idx]]
    nr = [str(v).strip() if v is not None else "" for v in all_rows[header_idx+1]] \
         if header_idx+1 < len(all_rows) else []
    merged = [f"{hr[i]} {nr[i] if i < len(nr) else ''}".strip() or f"Col_{i}" for i in range(len(hr))]

    col_map = {}
    for field in GSTR2B_COL_KEYWORDS:
        found = _find_col(merged, field, GSTR2B_COL_KEYWORDS)
        if found and found not in col_map.values(): col_map[field] = found

    essential = ["GSTIN","Invoice No","Invoice Date","Taxable","IGST","CGST","SGST"]
    found_ess = sum(1 for e in essential if e in col_map)

    data_start = None
    for ds in [header_idx+1, header_idx+2, header_idx+3]:
        if ds >= len(all_rows): continue
        for v in all_rows[ds]:
            sv = str(v).strip().upper().replace(" ","")
            if len(sv) == 15 and sv[:2].isdigit(): data_start = ds; break
        if data_start is not None: break
    if data_start is None:
        for i, row in enumerate(all_rows):
            for v in row:
                sv = str(v).strip().upper().replace(" ","")
                if len(sv) == 15 and sv[:2].isdigit(): data_start = i; break
            if data_start is not None: break
    if data_start is None:
        return pd.DataFrame(columns=list(B2B_COL_POS_FALLBACK.values())), b2b_name, det

    if found_ess >= 4:
        det["method"] = f"Column-Name Detection ({found_ess}/7 essential found)"
        det["col_map"] = col_map
        col_idx_map = {}
        for field, orig in col_map.items():
            for i, h in enumerate(merged):
                if h == orig: col_idx_map[field] = i; break
        records = []
        for row in all_rows[data_start:]:
            if not any(v is not None for v in row): continue
            gi = col_idx_map.get("GSTIN", 0)
            gv = row[gi] if gi < len(row) else None
            if gv is None: continue
            sv = str(gv).strip().upper().replace(" ","")
            if not (8 <= len(sv) <= 15): continue
            rec = {}
            for field in B2B_COL_POS_FALLBACK.values():
                idx = col_idx_map.get(field)
                rec[field] = row[idx] if idx is not None and idx < len(row) else None
            records.append(rec)
    else:
        det["method"] = "Fixed-Position Fallback"
        det["col_map"] = {v: f"Col {k}" for k, v in B2B_COL_POS_FALLBACK.items()}
        records = []
        for row in all_rows[data_start:]:
            if not any(v is not None for v in row): continue
            col_a = row[0] if row else None
            if col_a is None: continue
            sv = str(col_a).strip().upper().replace(" ","")
            if not (8 <= len(sv) <= 15): continue
            rec = {}
            for ci, cn in B2B_COL_POS_FALLBACK.items():
                rec[cn] = row[ci-1] if ci-1 < len(row) else None
            records.append(rec)

    if not records:
        return pd.DataFrame(columns=list(B2B_COL_POS_FALLBACK.values())), b2b_name, det

    df = pd.DataFrame(records)
    df["GSTIN"] = df["GSTIN"].astype(str).str.strip().str.upper().str.replace(r"\s+","",regex=True)
    df = df[df["GSTIN"].str.match(r"^\d{2}[A-Z]{5}\d{4}[A-Z]\d[Z][A-Z0-9]$", na=False)].copy()
    df["Vendor"]       = df.get("Vendor",     pd.Series([""]*len(df))).fillna("").astype(str).str.strip()
    df["Invoice No"]   = df.get("Invoice No", pd.Series([""]*len(df))).fillna("").astype(str).str.strip()
    df["Invoice Date"] = pd.to_datetime(df.get("Invoice Date"), errors="coerce", dayfirst=True)
    for col in ["Taxable","IGST","CGST","SGST","Cess","Invoice Value"]:
        if col in df.columns: df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0.0)
        else: df[col] = 0.0
    df["Total Tax"] = df["IGST"] + df["CGST"] + df["SGST"]
    return df.reset_index(drop=True), b2b_name, det


# ============================================================
#  BOOKS FILE READER — multi-engine with full fallback chain
# ============================================================
def _try_read_raw(raw: bytes) -> list[tuple]:
    """
    Try every possible engine to load the Excel bytes.
    Returns list of (sheet_name, all_rows_list) tuples, or raises clear error.
    Handles: .xlsx, .xls, .xlsb, .xlsm, CSV-in-xlsx, web-downloaded files,
             files with "no valid workbook part" openpyxl error.
    """
    results = []

    # Engine 1: openpyxl (handles .xlsx, .xlsm)
    try:
        wb = openpyxl.load_workbook(io.BytesIO(raw), read_only=False, data_only=True)
        for sn in wb.sheetnames:
            rows = list(wb[sn].iter_rows(values_only=True))
            if rows: results.append((sn, rows))
        if results: return results
    except Exception: pass

    # Engine 2: openpyxl read_only mode (sometimes works when normal mode fails)
    try:
        wb = openpyxl.load_workbook(io.BytesIO(raw), read_only=True, data_only=True)
        for sn in wb.sheetnames:
            rows = list(wb[sn].iter_rows(values_only=True))
            if rows: results.append((sn, rows))
        wb.close()
        if results: return results
    except Exception: pass

    # Engine 3: pandas ExcelFile with openpyxl engine
    try:
        xf = pd.ExcelFile(io.BytesIO(raw), engine="openpyxl")
        for sn in xf.sheet_names:
            df = xf.parse(sn, header=None)
            if not df.empty:
                rows = [tuple(r) for r in df.values.tolist()]
                results.append((sn, rows))
        if results: return results
    except Exception: pass

    # Engine 4: pandas with xlrd (handles older .xls files)
    try:
        xf = pd.ExcelFile(io.BytesIO(raw), engine="xlrd")
        for sn in xf.sheet_names:
            df = xf.parse(sn, header=None)
            if not df.empty:
                rows = [tuple(r) for r in df.values.tolist()]
                results.append((sn, rows))
        if results: return results
    except Exception: pass

    # Engine 5: pandas auto-detect engine
    try:
        xf = pd.ExcelFile(io.BytesIO(raw))
        for sn in xf.sheet_names:
            df = xf.parse(sn, header=None)
            if not df.empty:
                rows = [tuple(r) for r in df.values.tolist()]
                results.append((sn, rows))
        if results: return results
    except Exception: pass

    # Engine 6: Try treating as CSV (some files are CSV saved as .xlsx)
    try:
        import csv
        text = raw.decode("utf-8-sig", errors="replace")
        reader = csv.reader(io.StringIO(text))
        rows   = [tuple(r) for r in reader if any(c.strip() for c in r)]
        if len(rows) > 1:
            return [("Sheet1", rows)]
    except Exception: pass

    # Engine 7: Try latin-1 CSV
    try:
        import csv
        text = raw.decode("latin-1", errors="replace")
        reader = csv.reader(io.StringIO(text))
        rows   = [tuple(r) for r in reader if any(c.strip() for c in r)]
        if len(rows) > 1:
            return [("Sheet1", rows)]
    except Exception: pass

    # All engines failed
    raise ValueError(
        "Could not open the file. Please check:\n"
        "• The file is a valid Excel file (.xlsx or .xls)\n"
        "• The file is not password protected\n"
        "• The file is not corrupted\n"
        "• Try opening in Excel, then Save As → Excel Workbook (.xlsx) and re-upload"
    )


def _read_books_file(file_obj, manual_header_row=None, manual_sheet=None, sheet_type="B2B"):
    file_obj.seek(0); raw = file_obj.read()

    # Load using the multi-engine reader
    try:
        sheet_data = _try_read_raw(raw)   # [(sheet_name, all_rows), ...]
    except ValueError as e:
        raise ValueError(f"Purchase Register: {e}")

    best_df = None; best_score = -1; best_info = {}
    target  = ([s for s in sheet_data if s[0] == manual_sheet]
               if manual_sheet else sheet_data)
    if not target: target = sheet_data   # fallback if manual sheet not found
    
    # ── Sheet-type routing ──────────────────────────────────
    # CDNR sheet names from any accounting software:
    CDNR_SHEET_KEYWORDS = [
        "cdnr","cdn","cnr","dnr",
        "credit note","creditnote","cr note","cr-note","cr_note",
        "debit note","debitnote","dr note","dr-note","dr_note",
        "cn","dn","c/n","d/n","c.n","d.n",
        "credit","debit","note","notes",
        "credit debit","debit credit","cr dr","dr cr",
        "purchase return","sales return","return","refund",
        "amendment","cdnra","b2b-cdnr","b2bcdnr",
    ]
    if sheet_type == "CDNR":
        cdnr_target = []
        for sn, rows in target:
            sn_l = sn.lower().replace(" ","").replace("-","").replace("_","")
            if any(kw.replace(" ","") in sn_l for kw in CDNR_SHEET_KEYWORDS):
                cdnr_target.append((sn, rows))
        if not cdnr_target: return pd.DataFrame(), {}
        target = cdnr_target
    else:
        # For B2B: exclude any sheet that looks like CDNR
        excl_kws = ["cdnr","cdn","credit note","creditnote","debit note","debitnote",
                    "cr note","dr note","/cn","/dn","c/n","d/n","return","refund"]
        target = [s for s in target
                  if not any(kw in s[0].lower().replace(" ","") for kw in excl_kws)]

    for sn, all_rows in target:
        if not all_rows: continue
        hidx = (max(0, manual_header_row-1) if manual_header_row is not None
                else _find_header_row(all_rows, max_scan=20))
        if hidx >= len(all_rows): continue

        header = []; seen = {}
        for j, v in enumerate(all_rows[hidx]):
            h = str(v).strip() if v is not None and str(v).strip() not in ("None","nan","")                 else f"Col_{j}"
            if h in seen: seen[h] += 1; h = f"{h}_{seen[h]}"
            else: seen[h] = 0
            header.append(h)

        data_rows = []
        for row in all_rows[hidx+1:]:
            if any(v is not None and str(v).strip() not in ("","None","nan") for v in row):
                rl = list(row)
                while len(rl) < len(header): rl.append(None)
                data_rows.append(rl[:len(header)])
        if not data_rows: continue

        df = pd.DataFrame(data_rows, columns=header).dropna(how="all").reset_index(drop=True)
        score = 0
        for col in df.columns:
            vals = df[col].dropna().astype(str).str.strip()
            score += vals.str.match(r"^\d{2}[A-Z0-9]{13}$").sum() * 10
            if any(k in col.lower() for k in
                   ["gstin","gst","invoice","bill","taxable","igst","cgst","sgst"]):
                score += 5
        info = {"sheet": sn, "header_row": hidx+1, "score": score, "warnings": []}
        if score > best_score: best_score = score; best_df = df; best_info = info

    if best_df is None or best_df.empty:
        raise ValueError(
            "Purchase Register: file opened successfully but no data found.\n"
            "Possible reasons:\n"
            "• All sheets are empty\n"
            "• Column headers not found in first 20 rows\n"
            "Download the Sample Purchase Register to compare your file structure."
        )
    return best_df, best_info


# ============================================================
#  BOOKS NORMALIZER
# ============================================================
def _load_books(df_raw, extra_hints=None):
    df = df_raw.copy()
    df.columns = [str(c).strip() for c in df.columns]
    if extra_hints:
        for field, hint in extra_hints.items():
            if hint and field in BOOKS_COL_MAP:
                BOOKS_COL_MAP[field] = [hint.lower()] + BOOKS_COL_MAP[field]
    # Build mapping ensuring no column is claimed by two fields
    # Priority order: GSTIN first, then Invoice fields, then tax fields, then Vendor last
    _priority = ["GSTIN","Invoice No","Invoice Date","Invoice Value",
                 "Taxable","IGST","CGST","SGST","Vendor"]
    _other    = [f for f in BOOKS_COL_MAP if f not in _priority]
    mapping   = {}
    _claimed  = set()   # tracks which original columns are already assigned
    for field in _priority + _other:
        found = _find_col(list(df.columns), field, BOOKS_COL_MAP)
        if found and found not in _claimed:
            mapping[field] = found
            _claimed.add(found)
    df = df.rename(columns={v: k for k, v in mapping.items() if v in df.columns})
    for col in ["GSTIN","Invoice No","Vendor"]:
        if col not in df.columns: df[col] = ""
        df[col] = df[col].fillna("").astype(str).str.strip()
    # Deep-clean GSTIN: remove ALL whitespace including non-breaking spaces, zero-width chars
    df["GSTIN"] = (df["GSTIN"]
                   .str.upper()
                   .str.replace(r"[\s\u00a0\u200b\u200c\u200d\ufeff]+", "", regex=True))
    # Keep rows where GSTIN is 15 chars AND starts with 2 digits AND has letters
    # Use broad filter — let the matching engine handle quality
    gstin_15    = df["GSTIN"].str.len() == 15
    gstin_start = df["GSTIN"].str.match(r"^\d{2}", na=False)
    gstin_has_letters = df["GSTIN"].str.contains(r"[A-Z]", na=False)
    # Also accept UIN (starts with 88), embassy codes, etc. — just needs to be 10-15 chars
    gstin_partial = df["GSTIN"].str.len().between(10, 14)
    # Exclude obvious non-GSTINs: header text, "total", "nan", blank
    gstin_junk  = df["GSTIN"].str.match(
        r"^(NAN|NONE|TOTAL|GRAND|SUB|GSTIN|NA|NIL|N/A|NULL|-).*$", na=False)
    df = df[(((gstin_15 & gstin_start & gstin_has_letters) | gstin_partial) & ~gstin_junk)].copy()
    if df.empty:
        # Show sample of what GSTIN column actually contained before filtering
        _gstin_samples = df_raw.copy()
        _gstin_col_orig = mapping.get("GSTIN","")
        if _gstin_col_orig and _gstin_col_orig in _gstin_samples.columns:
            _samples = _gstin_samples[_gstin_col_orig].dropna().astype(str).head(5).tolist()
        else:
            _samples = list(_gstin_samples.columns[:5])
        df["Invoice Date"] = pd.NaT
        for c in ["IGST","CGST","SGST","Taxable"]: df[c] = 0.0
        df["Total Tax"] = 0.0
        # Store sample for better error message
        df.attrs["gstin_samples"] = _samples
        return df.reset_index(drop=True), mapping
    if "Invoice Date" not in df.columns: df["Invoice Date"] = pd.NaT
    else: df["Invoice Date"] = pd.to_datetime(df["Invoice Date"], errors="coerce", dayfirst=True)
    for c in ["IGST","CGST","SGST","Taxable"]:
        if c not in df.columns: df[c] = 0.0
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0.0)
    df["Total Tax"] = df["IGST"] + df["CGST"] + df["SGST"]
    return df.reset_index(drop=True), mapping


# ============================================================
#  CDNR BOOKS LOADER
#  Normalises a credit/debit note sheet from the Purchase Register
# ============================================================
def _load_cdnr_books(df_raw):
    """
    Like _load_books() but uses CDNR_BOOKS_COL_MAP.
    Handles all common credit/debit note column names from any accounting software.
    Returns (normalised_df, mapping_dict)
    """
    df = df_raw.copy()
    df.columns = [str(c).strip() for c in df.columns]

    # Priority: GSTIN first, then Note No / Note Date, then amounts, then Vendor last
    _priority = ["GSTIN","Note No","Note Date","Note Type","Note Value",
                 "Taxable","IGST","CGST","SGST","Vendor",
                 "Original Invoice No","Original Invoice Date"]
    _other    = [f for f in CDNR_BOOKS_COL_MAP if f not in _priority]
    mapping   = {}
    _claimed  = set()
    for field in _priority + _other:
        found = _find_col(list(df.columns), field, CDNR_BOOKS_COL_MAP)
        if found and found not in _claimed:
            mapping[field] = found
            _claimed.add(found)

    df = df.rename(columns={v: k for k, v in mapping.items() if v in df.columns})

    # Ensure key string columns exist
    for col in ["GSTIN","Note No","Vendor","Note Type"]:
        if col not in df.columns: df[col] = ""
        df[col] = df[col].fillna("").astype(str).str.strip()

    # Deep-clean GSTIN
    df["GSTIN"] = (df["GSTIN"]
                   .str.upper()
                   .str.replace(r"[\s\u00a0\u200b\u200c\u200d\ufeff]+","",regex=True))

    # Filter valid GSTINs
    gstin_15  = df["GSTIN"].str.len() == 15
    gstin_dig = df["GSTIN"].str.match(r"^\d{2}", na=False)
    gstin_let = df["GSTIN"].str.contains(r"[A-Z]", na=False)
    gstin_prt = df["GSTIN"].str.len().between(10, 14)
    gstin_jnk = df["GSTIN"].str.match(
        r"^(NAN|NONE|TOTAL|GRAND|SUB|GSTIN|NA|NIL|N/A|NULL|-).*$", na=False)
    df = df[(((gstin_15 & gstin_dig & gstin_let) | gstin_prt) & ~gstin_jnk)].copy()

    if df.empty:
        for c in ["IGST","CGST","SGST","Taxable","Note Value"]: df[c] = 0.0
        df["Total Tax"] = 0.0
        df["Note Date"] = pd.NaT
        return df.reset_index(drop=True), mapping

    # Dates
    for dc in ["Note Date","Original Invoice Date"]:
        if dc in df.columns:
            df[dc] = pd.to_datetime(df[dc], errors="coerce", dayfirst=True)
        else:
            df[dc] = pd.NaT

    # Numeric columns
    for c in ["IGST","CGST","SGST","Taxable","Note Value"]:
        if c not in df.columns: df[c] = 0.0
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0.0)
    df["Total Tax"] = df["IGST"] + df["CGST"] + df["SGST"]

    return df.reset_index(drop=True), mapping


# ============================================================
#  INVOICE MATCHING
# ============================================================
def _norm(s):   return re.sub(r"[^a-z0-9]","",str(s).lower().strip())
def _dig(s):    return re.sub(r"\D","",str(s))

def _match_invoice(a, b):
    if not a or not b or str(a) in ("nan","None","") or str(b) in ("nan","None",""): return False,""
    na,nb = _norm(a),_norm(b); da,db = _dig(a),_dig(b)
    if na==nb and na:                                       return True,"Exact"
    if da and db and da==db:                                return True,"Numeric Exact"
    if da and db and len(da)>=2 and len(db)>=2:
        if da.endswith(db) or db.endswith(da):              return True,"Numeric Suffix"
    ml = min(len(na),len(nb))
    if ml>=4:
        if na[-ml:]==nb[-ml:]:                              return True,"Alpha Suffix"
        if na[:ml]==nb[:ml]:                                return True,"Alpha Prefix"
    if da and db and len(da)>=3 and len(db)>=3:
        if da.lstrip("0")==db.lstrip("0"):                  return True,"Leading Zero"
        if da in db or db in da:                            return True,"Numeric Contains"
    na2,nb2 = na,nb
    for p in ["purchase","pur","bill","inv","gst","tax","rcm","import"]:
        if na2.startswith(p): na2=na2[len(p):]
        if nb2.startswith(p): nb2=nb2[len(p):]
    if na2 and nb2 and na2==nb2 and len(na2)>=3:            return True,"Prefix Stripped"
    return False,""


# ============================================================
#  RECONCILIATION ENGINE
# ============================================================
def run_cdnr_reco(gstr2b_file, books_cdnr_raw, date_tol, amt_tol, taxable_tol):
    """
    Dedicated CDNR reconciliation.
    Loads CDNR sheet from GSTR-2B, loads CN/DN sheet from books,
    matches by GSTIN + Note Number using all keyword variants.
    Returns (result_df, meta_dict)
    """
    # Load CDNR from GSTR-2B
    gstr2b_cdnr, cdnr_sheet, cdnr_det = _load_b2b_sheet(gstr2b_file, sheet_type="CDNR")
    if gstr2b_cdnr.empty:
        return pd.DataFrame(), {"cdnr_sheet": cdnr_sheet or "Not Found",
                                "cdnr_2b_count": 0, "cdnr_books_count": 0,
                                "cdnr_det": cdnr_det, "cdnr_b_map": {}}

    # Normalize GSTR-2B CDNR: Invoice No field holds Note No in CDNR context
    # Rename to consistent "Note No" for clarity in output
    if "Invoice No" in gstr2b_cdnr.columns and "Note No" not in gstr2b_cdnr.columns:
        gstr2b_cdnr = gstr2b_cdnr.rename(columns={
            "Invoice No":   "Note No",
            "Invoice Date": "Note Date",
            "Invoice Value":"Note Value",
            "Invoice Type": "Note Type",
        })
    if "Note No"   not in gstr2b_cdnr.columns: gstr2b_cdnr["Note No"]   = ""
    if "Note Date" not in gstr2b_cdnr.columns: gstr2b_cdnr["Note Date"] = pd.NaT
    if "Note Type" not in gstr2b_cdnr.columns: gstr2b_cdnr["Note Type"] = ""
    if "Note Value" not in gstr2b_cdnr.columns: gstr2b_cdnr["Note Value"] = 0.0

    # Load CN/DN sheet from books — graceful if missing
    books_cdnr = pd.DataFrame()
    cdnr_b_map = {}
    if books_cdnr_raw is not None and not books_cdnr_raw.empty:
        books_cdnr, cdnr_b_map = _load_cdnr_books(books_cdnr_raw)

    # Build GSTIN index on books CDNR
    by_gstin = {}
    by_pan   = {}
    if not books_cdnr.empty:
        for j, bk in books_cdnr.iterrows():
            by_gstin.setdefault(bk["GSTIN"], []).append((j, bk))
        for g, ents in by_gstin.items():
            if len(g) == 15: by_pan.setdefault(g[2:12], []).extend(ents)

    results = []; matched = set()

    for _, r2b in gstr2b_cdnr.iterrows():
        g2b  = str(r2b.get("GSTIN",""))
        n2b  = str(r2b.get("Note No",""))
        bj=bbk=None; bm=""

        cands = list(by_gstin.get(g2b,[]))
        if not cands and len(g2b)==15:
            cands = list(by_pan.get(g2b[2:12],[]))

        for j, bk in cands:
            if j in matched: continue
            bk_note = str(bk.get("Note No",""))
            ok, mt  = _match_invoice(n2b, bk_note)
            if ok: bj,bbk,bm=j,bk,mt; break

        def _f(row, k, default=0.0):
            v = row.get(k, default)
            try: return float(v) if v is not None and str(v).strip() not in ("","nan","None") else default
            except: return default

        if bbk is not None:
            matched.add(bj); bk = bbk
            dd = 0
            d2b = r2b.get("Note Date", pd.NaT)
            dbk = bk.get("Note Date", pd.NaT)
            if pd.notna(d2b) and pd.notna(dbk):
                try: dd = abs((pd.to_datetime(d2b) - pd.to_datetime(dbk)).days)
                except: dd = 0
            diffs = []
            if dd > date_tol: diffs.append(f"Date Diff ({dd}d)")
            for fld,tol in [("IGST",amt_tol),("CGST",amt_tol),("SGST",amt_tol),("Taxable",taxable_tol)]:
                v2 = _f(r2b, fld); vb = _f(bk, fld)
                if abs(v2-vb) > tol: diffs.append(f"{fld} Diff ₹{abs(v2-vb):,.2f}")
            results.append({
                "GSTIN":             g2b,
                "Vendor (2B)":       r2b.get("Vendor",""),
                "Vendor (Books)":    bk.get("Vendor",""),
                "Note No (2B)":      n2b,
                "Note No (Books)":   bk.get("Note No",""),
                "Note Type":         r2b.get("Note Type",""),
                "Note Date (2B)":    d2b,
                "Note Date (Books)": dbk,
                "Note Value (2B)":   _f(r2b,"Note Value"),
                "Taxable (2B)":      _f(r2b,"Taxable"),
                "Taxable (Books)":   _f(bk,"Taxable"),
                "IGST (2B)":         _f(r2b,"IGST"),
                "IGST (Books)":      _f(bk,"IGST"),
                "CGST (2B)":         _f(r2b,"CGST"),
                "CGST (Books)":      _f(bk,"CGST"),
                "SGST (2B)":         _f(r2b,"SGST"),
                "SGST (Books)":      _f(bk,"SGST"),
                "Total Tax (2B)":    _f(r2b,"Total Tax"),
                "Total Tax (Books)": _f(bk,"Total Tax"),
                "ITC":               r2b.get("ITC",""),
                "Match Method":      bm,
                "Status":            "MATCHED WITH DIFF" if diffs else "MATCHED",
                "Remarks":           " | ".join(diffs) if diffs else "Exact Match",
            })
        else:
            results.append({
                "GSTIN":             g2b,
                "Vendor (2B)":       r2b.get("Vendor",""),
                "Vendor (Books)":    "",
                "Note No (2B)":      n2b,
                "Note No (Books)":   "",
                "Note Type":         r2b.get("Note Type",""),
                "Note Date (2B)":    r2b.get("Note Date", pd.NaT),
                "Note Date (Books)": pd.NaT,
                "Note Value (2B)":   _f(r2b,"Note Value"),
                "Taxable (2B)":      _f(r2b,"Taxable"),
                "Taxable (Books)":   None,
                "IGST (2B)":         _f(r2b,"IGST"),
                "IGST (Books)":      None,
                "CGST (2B)":         _f(r2b,"CGST"),
                "CGST (Books)":      None,
                "SGST (2B)":         _f(r2b,"SGST"),
                "SGST (Books)":      None,
                "Total Tax (2B)":    _f(r2b,"Total Tax"),
                "Total Tax (Books)": None,
                "ITC":               r2b.get("ITC",""),
                "Match Method":      "",
                "Status":            "IN 2B – NOT IN BOOKS",
                "Remarks":           "Note not found in Purchase Register",
            })

    # Books CN/DN not in 2B
    for j, bk in books_cdnr.iterrows():
        if j not in matched:
            results.append({
                "GSTIN":             bk.get("GSTIN",""),
                "Vendor (2B)":       "",
                "Vendor (Books)":    bk.get("Vendor",""),
                "Note No (2B)":      "",
                "Note No (Books)":   bk.get("Note No",""),
                "Note Type":         bk.get("Note Type",""),
                "Note Date (2B)":    pd.NaT,
                "Note Date (Books)": bk.get("Note Date", pd.NaT),
                "Note Value (2B)":   None,
                "Taxable (2B)":      None,
                "Taxable (Books)":   _f(bk,"Taxable"),
                "IGST (2B)":         None,
                "IGST (Books)":      _f(bk,"IGST"),
                "CGST (2B)":         None,
                "CGST (Books)":      _f(bk,"CGST"),
                "SGST (2B)":         None,
                "SGST (Books)":      _f(bk,"SGST"),
                "Total Tax (2B)":    None,
                "Total Tax (Books)": _f(bk,"Total Tax"),
                "ITC":               "",
                "Match Method":      "",
                "Status":            "IN BOOKS – NOT IN 2B",
                "Remarks":           "Note not uploaded on GST Portal",
            })

    out = pd.DataFrame(results) if results else pd.DataFrame()
    meta = {
        "cdnr_sheet":       cdnr_sheet or "Not Found",
        "cdnr_2b_count":    len(gstr2b_cdnr),
        "cdnr_books_count": len(books_cdnr),
        "cdnr_det":         cdnr_det,
        "cdnr_b_map":       cdnr_b_map,
    }
    return out, meta


def run_reco(gstr2b_file, books_df_raw, date_tol, amt_tol, taxable_tol, extra_hints=None, sheet_type="B2B"):
    gstr2b, b2b_sheet, gstr2b_det = _load_b2b_sheet(gstr2b_file, sheet_type=sheet_type)
    if sheet_type == "CDNR" and (gstr2b.empty or books_df_raw.empty):
        return pd.DataFrame(), {}
    books,  b_map                 = _load_books(books_df_raw, extra_hints)
    if gstr2b.empty:
        raise ValueError(f"B2B sheet '{b2b_sheet}' has no valid data rows.")
    if books.empty:
        col_list = list(books_df_raw.columns[:20])
        mapped   = list(b_map.keys()) if b_map else []
        gstin_samples = books.attrs.get("gstin_samples", [])
        raise ValueError(
            f"Purchase Register: no rows with valid GSTIN found after processing.\n\n"
            f"Columns detected in your file:\n{col_list}\n\n"
            f"Fields successfully mapped: {mapped}\n\n"
            + (f"Sample values found in GSTIN column: {gstin_samples}\n\n" if gstin_samples else "")
            + "Possible reasons:\n"
            "• GSTIN column values may have invisible characters — copy-paste from portal PDF can cause this\n"
            "• All rows may be summary/total rows without GSTINs\n"
            "• Header row not detected correctly — file may have merged cells or multiple title rows\n"
            "• Download the Sample Purchase Register and compare your file structure"
        )
    by_gstin = {}
    for j, bk in books.iterrows(): by_gstin.setdefault(bk["GSTIN"], []).append((j, bk))
    by_pan = {}
    for g, ents in by_gstin.items():
        if len(g)==15: by_pan.setdefault(g[2:12],[]).extend(ents)

    results=[]; matched=set()
    for _, r2b in gstr2b.iterrows():
        g2b=r2b["GSTIN"]; i2b=str(r2b["Invoice No"])
        bj=bbk=None; bm=""
        cands = list(by_gstin.get(g2b,[]))
        if not cands and len(g2b)==15: cands=list(by_pan.get(g2b[2:12],[]))
        for j,bk in cands:
            if j in matched: continue
            ok,mt = _match_invoice(i2b, str(bk["Invoice No"]))
            if ok: bj,bbk,bm=j,bk,mt; break

        if bbk is not None:
            matched.add(bj); bk=bbk
            dd=0
            if pd.notna(r2b["Invoice Date"]) and pd.notna(bk["Invoice Date"]):
                dd=abs((r2b["Invoice Date"]-bk["Invoice Date"]).days)
            diffs=[]
            if dd                                  > date_tol:    diffs.append(f"Date Diff ({dd}d)")
            if abs(r2b["IGST"]   -bk["IGST"])      > amt_tol:     diffs.append(f"IGST Diff ₹{abs(r2b['IGST']-bk['IGST']):,.2f}")
            if abs(r2b["CGST"]   -bk["CGST"])      > amt_tol:     diffs.append(f"CGST Diff ₹{abs(r2b['CGST']-bk['CGST']):,.2f}")
            if abs(r2b["SGST"]   -bk["SGST"])      > amt_tol:     diffs.append(f"SGST Diff ₹{abs(r2b['SGST']-bk['SGST']):,.2f}")
            if abs(r2b["Taxable"]-bk["Taxable"])   > taxable_tol: diffs.append(f"Taxable Diff ₹{abs(r2b['Taxable']-bk['Taxable']):,.2f}")
            results.append({"GSTIN":g2b,"GSTIN (2B)": g2b, "GSTIN (Books)": bk["GSTIN"], "Vendor (2B)":r2b["Vendor"],"Vendor (Books)":bk.get("Vendor",""),
                "Invoice No (2B)":r2b["Invoice No"],"Invoice No (Books)":bk["Invoice No"],
                "Invoice Date (2B)":r2b["Invoice Date"],"Invoice Date (Books)":bk["Invoice Date"],
                "Taxable (2B)":r2b["Taxable"],"Taxable (Books)":bk["Taxable"],
                "IGST (2B)":r2b["IGST"],"IGST (Books)":bk["IGST"],
                "CGST (2B)":r2b["CGST"],"CGST (Books)":bk["CGST"],
                "SGST (2B)":r2b["SGST"],"SGST (Books)":bk["SGST"],
                "Total Tax (2B)":r2b["Total Tax"],"Total Tax (Books)":bk["Total Tax"],
                "Rev Charge": r2b.get("Rev Charge", ""), "ITC": r2b.get("ITC", ""), "ITC Reason": r2b.get("ITC Reason", ""),
                "Match Method":bm,
                "Status":"MATCHED WITH DIFF" if diffs else "MATCHED",
                "Remarks":" | ".join(diffs) if diffs else "Exact Match"})
        else:
            results.append({"GSTIN":g2b,"GSTIN (2B)": g2b, "GSTIN (Books)": "", "Vendor (2B)":r2b["Vendor"],"Vendor (Books)":"",
                "Invoice No (2B)":r2b["Invoice No"],"Invoice No (Books)":"",
                "Invoice Date (2B)":r2b["Invoice Date"],"Invoice Date (Books)":pd.NaT,
                "Taxable (2B)":r2b["Taxable"],"Taxable (Books)":None,
                "IGST (2B)":r2b["IGST"],"IGST (Books)":None,
                "CGST (2B)":r2b["CGST"],"CGST (Books)":None,
                "SGST (2B)":r2b["SGST"],"SGST (Books)":None,
                "Total Tax (2B)":r2b["Total Tax"],"Total Tax (Books)":None,
                "Rev Charge": r2b.get("Rev Charge", ""), "ITC": r2b.get("ITC", ""), "ITC Reason": r2b.get("ITC Reason", ""),
                "Match Method":"",
                "Status":"IN 2B – NOT IN BOOKS","Remarks":"Not found in Purchase Register"})

    for j, bk in books.iterrows():
        if j not in matched:
            results.append({"GSTIN":bk["GSTIN"],"GSTIN (2B)": "", "GSTIN (Books)": bk["GSTIN"], "Vendor (2B)":"","Vendor (Books)":bk.get("Vendor",""),
                "Invoice No (2B)":"","Invoice No (Books)":bk["Invoice No"],
                "Invoice Date (2B)":pd.NaT,"Invoice Date (Books)":bk["Invoice Date"],
                "Taxable (2B)":None,"Taxable (Books)":bk["Taxable"],
                "IGST (2B)":None,"IGST (Books)":bk["IGST"],
                "CGST (2B)":None,"CGST (Books)":bk["CGST"],
                "SGST (2B)":None,"SGST (Books)":bk["SGST"],
                "Total Tax (2B)":None,"Total Tax (Books)":bk["Total Tax"],
                "Rev Charge": "", "ITC": "", "ITC Reason": "",
                "Match Method":"",
                "Status":"IN BOOKS – NOT IN 2B","Remarks":"Not uploaded on GST Portal"})

    out  = pd.DataFrame(results) if results else pd.DataFrame()
    meta = {"b2b_sheet":b2b_sheet,"b2b_count":len(gstr2b),"books_count":len(books),
            "b_map":b_map,"books_cols":list(books_df_raw.columns[:25]),"gstr2b_det":gstr2b_det}
    return out, meta


# ============================================================
#  ADVANCE EXCEL REPORT — 4 colour-coded sheets with guidance
# ============================================================
def build_advance_excel(df, cdnr_df=None):
    wb   = Workbook(); wb.remove(wb.active)
    thin = Side(style="thin",  color="D0D0D0")
    med  = Side(style="medium",color="B0B0B0")
    bdr  = Border(left=thin,  right=thin,  top=thin,  bottom=thin)
    mbdr = Border(left=med,   right=med,   top=med,   bottom=med)

    # ── Colour palette ──────────────────────────────────────
    C = {
        "navy":    "1F3864", "blue":    "2E75B6", "dkblue":  "1F4E79",
        "green":   "375623", "dkgreen": "1E4620", "ltgreen": "E2EFDA",
        "amber":   "7B4F00", "ltamber": "FFF2CC", "dkamber": "BF8F00",
        "red":     "843C0C", "ltred":   "FCE4D6", "dkred":   "C00000",
        "blue2":   "0D3D5E", "ltblue":  "DAEEF3",
        "orange":  "7F3F00", "ltorange":"FFF3E0",
        "purple":  "4B0082", "ltpurple":"F3E8FF",
        "grey":    "6B7280", "ltgrey":  "F8FAFC",
        "white":   "FFFFFF",
    }
    MONEY_KW = ["Taxable","IGST","CGST","SGST","Total Tax","Note Value","Value","Amount"]
    STATUS_CLR = {
        "MATCHED":            (C["ltgreen"],  C["dkgreen"]),
        "MATCHED WITH DIFF":  (C["ltamber"],  C["amber"]),
        "IN 2B – NOT IN BOOKS":(C["ltred"],   C["red"]),
        "IN BOOKS – NOT IN 2B":(C["ltblue"],  C["blue2"]),
    }

    def _bdr(): return Border(left=thin,right=thin,top=thin,bottom=thin)

    def _title_row(ws, text, ncols, bg, row=1, h=28):
        ws.merge_cells(f"A{row}:{get_column_letter(ncols)}{row}")
        c = ws.cell(row=row, column=1, value=text)
        c.font      = Font(name="Calibri",bold=True,size=13,color=C["white"])
        c.fill      = PatternFill("solid",fgColor=bg)
        c.alignment = Alignment(horizontal="center",vertical="center")
        ws.row_dimensions[row].height = h

    def _guidance_row(ws, text, ncols, row=2, bg="FFF8E7", fg="78350F"):
        ws.merge_cells(f"A{row}:{get_column_letter(ncols)}{row}")
        c = ws.cell(row=row, column=1, value=f"ℹ  {text}")
        c.font      = Font(name="Calibri",size=9,color=fg,italic=True)
        c.fill      = PatternFill("solid",fgColor=bg)
        c.alignment = Alignment(horizontal="left",vertical="center",indent=1)
        ws.row_dimensions[row].height = 18

    def _header_row(ws, headers, row=3, bg="2E75B6"):
        for ci,h in enumerate(headers,1):
            c = ws.cell(row=row,column=ci,value=h)
            c.font      = Font(name="Calibri",bold=True,size=10,color=C["white"])
            c.fill      = PatternFill("solid",fgColor=bg)
            c.alignment = Alignment(horizontal="center",vertical="center",wrap_text=True)
            c.border    = _bdr()
        ws.row_dimensions[row].height = 24

    def _data_row(ws, r, values, bg=C["white"], fg="111111", money_cols=None, bold_cols=None):
        money_cols = money_cols or set()
        bold_cols  = bold_cols  or set()
        for ci,val in enumerate(values,1):
            cell = ws.cell(row=r,column=ci,value=val)
            cell.fill   = PatternFill("solid",fgColor=bg)
            cell.border = _bdr()
            cell.font   = Font(name="Calibri",size=10,color=fg,bold=(ci in bold_cols))
            if ci in money_cols:
                cell.number_format = "##,##,##0.00"
                cell.alignment     = Alignment(horizontal="right",vertical="center")
            else:
                cell.alignment = Alignment(horizontal="left",vertical="center",wrap_text=False)
        ws.row_dimensions[r].height = 17

    def _set_col_widths(ws, headers, widths_map):
        for ci,col in enumerate(headers,1):
            ws.column_dimensions[get_column_letter(ci)].width = widths_map.get(col,16)

    def _total_row(ws, r, ncols, values, money_cols, bg="1F3864", fg=C["white"]):
        for ci in range(1, ncols+1):
            val  = values.get(ci,"")
            cell = ws.cell(row=r,column=ci,value=val)
            cell.fill   = PatternFill("solid",fgColor=bg)
            cell.border = _bdr()
            cell.font   = Font(name="Calibri",size=10,bold=True,color=fg)
            if ci in money_cols:
                cell.number_format = "##,##,##0.00"
                cell.alignment     = Alignment(horizontal="right",vertical="center")
            else:
                cell.alignment = Alignment(horizontal="left",vertical="center")
        ws.row_dimensions[r].height = 18

    CW = {
        "GSTIN":22,"Vendor (2B)":26,"Vendor (Books)":26,"Vendor Name":28,
        "Invoice No (2B)":20,"Invoice No (Books)":20,
        "Note No (2B)":20,"Note No (Books)":20,
        "Invoice Date (2B)":16,"Invoice Date (Books)":16,
        "Note Date (2B)":16,"Note Date (Books)":16,
        "Taxable (2B)":15,"Taxable (Books)":15,
        "IGST (2B)":13,"IGST (Books)":13,
        "CGST (2B)":13,"CGST (Books)":13,
        "SGST (2B)":13,"SGST (Books)":13,
        "Total Tax (2B)":15,"Total Tax (Books)":15,
        "Note Value (2B)":15,"Note Type":14,
        "Diff (Taxable)":16,"Status":24,"Remarks":38,
        "ITC":12,"ITC Reason":22,"Rev Charge":14,"Match Method":18,
        "Invoice Count (2B)":16,"Invoice Count (Books)":18,
    }

    # ══════════════════════════════════════════════════════════
    # SHEET 1 — Vendor-wise Summary
    # ══════════════════════════════════════════════════════════
    ws1 = wb.create_sheet("1. Vendor-wise Summary")
    ws1.sheet_properties.tabColor = C["green"]

    v_hdrs = ["GSTIN","Vendor Name","Invoices in 2B","Invoices in Books",
              "Taxable Value (2B) ₹","Taxable Value (Books) ₹",
              "Total GST (2B) ₹","Diff (Taxable) ₹"]
    ncols1 = len(v_hdrs)
    _title_row(ws1,
        f"ADVANCE REPORT — Sheet 1: Vendor / Supplier-wise Invoice Summary  "
        f"|  Generated: {datetime.now().strftime('%d-%b-%Y %H:%M')}",
        ncols1, C["green"])
    _guidance_row(ws1,
        "This sheet shows a GSTIN-wise summary comparing total invoices, amounts and tax in GSTR-2B versus your "
        "Purchase Register. Rows highlighted RED indicate a taxable value difference — investigate and correct. "
        "Green = fully matched. Yellow = matched with differences. Check 'Diff (Taxable)' column for discrepancies.",
        ncols1, row=2, bg="F0FDF4", fg="166534")
    _header_row(ws1, v_hdrs, row=3, bg=C["green"])
    ws1.freeze_panes = "A4"

    match_df = df[df["GSTIN"].notna()].copy()
    grp = match_df.groupby("GSTIN")
    MONEY1 = {ci for ci,h in enumerate(v_hdrs,1) if any(k in h for k in MONEY_KW)}
    row_i = 4
    for gstin, g in grp:
        vname = ""
        for src in ["Vendor (2B)","Vendor (Books)"]:
            if src in g.columns:
                vals = g[src].dropna().astype(str).replace("","pd_na").replace("pd_na",pd.NA).dropna()
                if len(vals): vname = vals.iloc[0]; break
        n2b   = (g["Invoice No (2B)"]   != "").sum()   if "Invoice No (2B)"    in g.columns else 0
        nbks  = (g["Invoice No (Books)"]!= "").sum()   if "Invoice No (Books)" in g.columns else 0
        nm    = (g["Status"]=="MATCHED").sum()
        nd    = (g["Status"]=="MATCHED WITH DIFF").sum()
        n2o   = (g["Status"]=="IN 2B – NOT IN BOOKS").sum()
        nbo   = (g["Status"]=="IN BOOKS – NOT IN 2B").sum()
        t2b   = g["Taxable (2B)"].fillna(0).sum()   if "Taxable (2B)"   in g.columns else 0
        tbk   = g["Taxable (Books)"].fillna(0).sum() if "Taxable (Books)" in g.columns else 0
        gtx   = g["Total Tax (2B)"].fillna(0).sum()  if "Total Tax (2B)" in g.columns else 0
        diff  = t2b - tbk
        rmk   = "✅ Matched" if abs(diff) < 0.01 else f"⚠ Taxable Diff ₹{diff:,.2f}"
        if n2o > 0: rmk += f" | {n2o} invoice(s) not in books"
        if nbo > 0: rmk += f" | {nbo} invoice(s) not in 2B"
        # Row colour: green=perfect, yellow=diff, red=missing
        if n2o > 0 or nbo > 0:
            row_bg = C["ltred"]
        elif abs(diff) > 0.01 or nd > 0:
            row_bg = C["ltamber"]
        else:
            row_bg = C["ltgreen"]
        _data_row(ws1, row_i,
                  [gstin,vname,n2b,nbks,t2b,tbk,gtx,diff],
                  bg=row_bg, fg="1F3864", money_cols=MONEY1)
        row_i += 1

    # Grand total row
    _total_row(ws1, row_i, ncols1, {
        1:"", 2:"GRAND TOTAL",
        3:(df["Invoice No (2B)"]   != "").sum() if "Invoice No (2B)"   in df.columns else 0,
        4:(df["Invoice No (Books)"]!= "").sum() if "Invoice No (Books)" in df.columns else 0,
        5: df["Taxable (2B)"].fillna(0).sum()   if "Taxable (2B)"   in df.columns else 0,
        6:df["Taxable (Books)"].fillna(0).sum() if "Taxable (Books)" in df.columns else 0,
        7:df["Total Tax (2B)"].fillna(0).sum()  if "Total Tax (2B)" in df.columns else 0,
        8:(df["Taxable (2B)"].fillna(0).sum() if "Taxable (2B)" in df.columns else 0)
           -(df["Taxable (Books)"].fillna(0).sum() if "Taxable (Books)" in df.columns else 0),
    }, MONEY1)
    _set_col_widths(ws1, v_hdrs, CW)

    # ══════════════════════════════════════════════════════════
    # SHEET 2 — Purchase Bills in GSTR-2B NOT in Books
    # ══════════════════════════════════════════════════════════
    ws2 = wb.create_sheet("2. In 2B - Not in Books")
    ws2.sheet_properties.tabColor = C["red"]
    only2b  = df[df["Status"]=="IN 2B – NOT IN BOOKS"].copy()
    cols2   = [c for c in df.columns if "(Books)" not in c
               and c not in ["Match Method", "Rev Charge", "ITC", "ITC Reason", "Status", "Remarks", "Match Tier"] ]
    cols2   = [c for c in cols2 if c in only2b.columns]
    ncols2  = len(cols2)
    _title_row(ws2,
        f"ADVANCE REPORT — Sheet 2: Purchase Bills in GSTR-2B — NOT in Books  "
        f"({len(only2b)} records)  |  {datetime.now().strftime('%d-%b-%Y')}",
        ncols2, C["red"])
    _guidance_row(ws2,
        "These invoices are uploaded by your SUPPLIER on the GST Portal (appear in your GSTR-2B) but are "
        "NOT recorded in your Purchase Register. Action Required: Check if purchase was received — "
        "if yes, enter the bill in your accounting software. You CANNOT claim ITC on unrecorded purchases.",
        ncols2, row=2, bg="FFF1EC", fg="843C0C")
    _header_row(ws2, cols2, row=3, bg=C["red"])
    ws2.freeze_panes = "A4"
    MONEY2 = {ci for ci,c in enumerate(cols2,1) if any(k in c for k in MONEY_KW)}
    for ri,(_,row) in enumerate(only2b[cols2].iterrows()):
        _data_row(ws2, 4+ri, list(row),
                  bg=C["ltred"] if ri%2==0 else "FFF1EC",
                  fg="3D1200", money_cols=MONEY2)
    if not only2b.empty:
        tv = {ci:0 for ci in MONEY2}
        for ci in MONEY2:
            col = cols2[ci-1]
            if col in only2b.columns: tv[ci] = only2b[col].fillna(0).sum()
        tv[1]=""; tv[2]="TOTAL"
        _total_row(ws2, 4+len(only2b), ncols2, tv, MONEY2, bg=C["red"])
    _set_col_widths(ws2, cols2, CW)

    # ══════════════════════════════════════════════════════════
    # SHEET 3 — Purchase Bills in Books NOT in GSTR-2B
    # ══════════════════════════════════════════════════════════
    ws3 = wb.create_sheet("3. In Books - Not in 2B")
    ws3.sheet_properties.tabColor = C["blue2"]
    onlybk  = df[df["Status"]=="IN BOOKS – NOT IN 2B"].copy()
    cols3   = [c for c in df.columns if "(2B)" not in c
               and c not in ["Match Method", "Rev Charge", "ITC", "ITC Reason", "Status", "Remarks", "Match Tier"]]
    cols3   = [c for c in cols3 if c in onlybk.columns]
    ncols3  = len(cols3)
    _title_row(ws3,
        f"ADVANCE REPORT — Sheet 3: Purchase Bills in Books — NOT in GSTR-2B  "
        f"({len(onlybk)} records)  |  {datetime.now().strftime('%d-%b-%Y')}",
        ncols3, C["blue2"])
    _guidance_row(ws3,
        "These invoices are recorded in YOUR Purchase Register but your SUPPLIER has NOT uploaded them on "
        "the GST Portal (not appearing in GSTR-2B). Action Required: Contact your supplier and ask them "
        "to file GSTR-1 for these invoices. DO NOT claim ITC on these until they appear in GSTR-2B.",
        ncols3, row=2, bg="EEF8FC", fg="0D3D5E")
    _header_row(ws3, cols3, row=3, bg=C["blue2"])
    ws3.freeze_panes = "A4"
    MONEY3 = {ci for ci,c in enumerate(cols3,1) if any(k in c for k in MONEY_KW)}
    for ri,(_,row) in enumerate(onlybk[cols3].iterrows()):
        _data_row(ws3, 4+ri, list(row),
                  bg=C["ltblue"] if ri%2==0 else "EEF8FC",
                  fg="0D2B3E", money_cols=MONEY3)
    if not onlybk.empty:
        tv = {ci:0 for ci in MONEY3}
        for ci in MONEY3:
            col = cols3[ci-1]
            if col in onlybk.columns: tv[ci] = onlybk[col].fillna(0).sum()
        tv[1]=""; tv[2]="TOTAL"
        _total_row(ws3, 4+len(onlybk), ncols3, tv, MONEY3, bg=C["blue2"])
    _set_col_widths(ws3, cols3, CW)

    # ══════════════════════════════════════════════════════════
    # SHEET 4 — RCM Invoices + Ineligible ITC
    # ══════════════════════════════════════════════════════════
    ws4 = wb.create_sheet("4. RCM & Ineligible ITC")
    ws4.sheet_properties.tabColor = C["orange"]
    df_copy = df.copy()
    for c in ["Rev Charge","ITC","ITC Reason"]:
        if c not in df_copy.columns: df_copy[c] = ""
        df_copy[c] = df_copy[c].fillna("").astype(str)
    rcm_mask   = df_copy["Rev Charge"].str.strip().str.upper().isin(["Y","YES","TRUE","1","RCM"])
    inelig_mask= df_copy["ITC"].str.strip().str.upper().str.contains(
        r"^(NO|N|INELIGIBLE|NOT ELIGIBLE|BLOCKED|EXEMPT)$", na=False, regex=True)
    rcm_df   = df_copy[rcm_mask].copy()
    inelig_df= df_copy[inelig_mask].copy()
    rcm_cols = [c for c in ["GSTIN","Vendor (2B)","Invoice No (2B)","Invoice Date (2B)",
                             "Taxable (2B)","IGST (2B)","CGST (2B)","SGST (2B)",
                             "Total Tax (2B)"]
                if c in df_copy.columns]
    ncols4 = len(rcm_cols)
    _title_row(ws4,
        f"ADVANCE REPORT — Sheet 4: RCM Invoices & Ineligible ITC  "
        f"|  {datetime.now().strftime('%d-%b-%Y')}",
        ncols4, C["orange"])
    _guidance_row(ws4,
        "SECTION A (Orange): RCM (Reverse Charge Mechanism) invoices — tax is payable by YOU (the buyer), "
        "not the supplier. File these in GSTR-3B under RCM. | "
        "SECTION B (Red): Ineligible / Blocked ITC — these invoices appear in 2B but ITC CANNOT be claimed "
        "(e.g. personal expenses, blocked credit under Section 17(5)).",
        ncols4, row=2, bg="FFF3E0", fg="7F3F00")
    ws4.freeze_panes = "A4"
    MONEY4 = {ci for ci,c in enumerate(rcm_cols,1) if any(k in c for k in MONEY_KW)}

    # Section A header
    ws4.merge_cells(f"A3:{get_column_letter(ncols4)}3")
    sa = ws4.cell(row=3,column=1,value=f"  SECTION A — RCM (Reverse Charge) Invoices  ({len(rcm_df)} records)")
    sa.font      = Font(name="Calibri",bold=True,size=11,color=C["white"])
    sa.fill      = PatternFill("solid",fgColor=C["orange"])
    sa.alignment = Alignment(horizontal="left",vertical="center",indent=1)
    ws4.row_dimensions[3].height = 22

    _header_row(ws4, rcm_cols, row=4, bg="C55A11")
    rcm_end = 5
    if not rcm_df.empty:
        for ri,(_,row) in enumerate(rcm_df[rcm_cols].iterrows()):
            _data_row(ws4, 5+ri, list(row),
                      bg=C["ltorange"] if ri%2==0 else "FFF8F0",
                      fg="3D1200", money_cols=MONEY4)
        rcm_end = 5 + len(rcm_df)
        tv = {ci:0 for ci in MONEY4}
        for ci in MONEY4:
            col = rcm_cols[ci-1]
            if col in rcm_df.columns: tv[ci] = rcm_df[col].fillna(0).sum()
        tv[1]=""; tv[2]="RCM TOTAL"
        _total_row(ws4, rcm_end, ncols4, tv, MONEY4, bg=C["orange"])
        rcm_end += 1
    else:
        ws4.cell(row=5,column=1).value = "No RCM invoices found (Reverse Charge column not present or no RCM entries)."
        ws4.cell(row=5,column=1).font  = Font(name="Calibri",size=11,color=C["grey"],italic=True)
        rcm_end = 6

    # Section B header
    sb_row = rcm_end + 1
    ws4.merge_cells(f"A{sb_row}:{get_column_letter(ncols4)}{sb_row}")
    sb = ws4.cell(row=sb_row,column=1,
                  value=f"  SECTION B — Ineligible / Blocked ITC Invoices  ({len(inelig_df)} records)")
    sb.font      = Font(name="Calibri",bold=True,size=11,color=C["white"])
    sb.fill      = PatternFill("solid",fgColor=C["dkred"])
    sb.alignment = Alignment(horizontal="left",vertical="center",indent=1)
    ws4.row_dimensions[sb_row].height = 22
    _header_row(ws4, rcm_cols, row=sb_row+1, bg=C["dkred"])
    if not inelig_df.empty:
        for ri,(_,row) in enumerate(inelig_df[rcm_cols].iterrows()):
            _data_row(ws4, sb_row+2+ri, list(row),
                      bg="FFCCCC" if ri%2==0 else "FFE5E5",
                      fg="3D0000", money_cols=MONEY4)
        itv = {ci:0 for ci in MONEY4}
        for ci in MONEY4:
            col = rcm_cols[ci-1]
            if col in inelig_df.columns: itv[ci] = inelig_df[col].fillna(0).sum()
        itv[1]=""; itv[2]="INELIGIBLE TOTAL"
        _total_row(ws4, sb_row+2+len(inelig_df), ncols4, itv, MONEY4, bg=C["dkred"])
    else:
        ws4.cell(row=sb_row+2,column=1).value = "No ineligible ITC invoices found."
        ws4.cell(row=sb_row+2,column=1).font  = Font(name="Calibri",size=11,color=C["grey"],italic=True)
    _set_col_widths(ws4, rcm_cols, CW)

    # ══════════════════════════════════════════════════════════
    # SHEET 5 (bonus) — CDNR Reconciliation if available
    # ══════════════════════════════════════════════════════════
    if cdnr_df is not None and not cdnr_df.empty:
        ws5 = wb.create_sheet("5. CDNR Reconciliation")
        ws5.sheet_properties.tabColor = C["purple"]
        cdnr_cols = [c for c in cdnr_df.columns if c not in ["Rev Charge", "ITC", "ITC Reason", "Status", "Remarks", "Match Tier"]]
        ncols5    = len(cdnr_cols)
        matched_c = (cdnr_df["Status"]=="MATCHED").sum()             if "Status" in cdnr_df.columns else 0
        diff_c    = (cdnr_df["Status"]=="MATCHED WITH DIFF").sum()   if "Status" in cdnr_df.columns else 0
        only2b_c  = (cdnr_df["Status"]=="IN 2B – NOT IN BOOKS").sum()if "Status" in cdnr_df.columns else 0
        onlybk_c  = (cdnr_df["Status"]=="IN BOOKS – NOT IN 2B").sum()if "Status" in cdnr_df.columns else 0
        _title_row(ws5,
            f"ADVANCE REPORT — Sheet 5: Credit / Debit Note (CDNR) Reconciliation  "
            f"({len(cdnr_df)} notes)  |  {datetime.now().strftime('%d-%b-%Y %H:%M')}",
            ncols5, C["purple"])
        _guidance_row(ws5,
            f"Matches credit/debit notes from GSTR-2B (CDNR sheet) against your Purchase Return / "
            f"CN-DN register. Summary: Matched={matched_c} | With Diff={diff_c} | "
            f"In 2B only={only2b_c} | In Books only={onlybk_c}. "
            f"Green=matched, Yellow=difference found, Red=in 2B not in books, Blue=in books not in 2B.",
            ncols5, row=2, bg=C["ltpurple"], fg=C["purple"])
        _header_row(ws5, cdnr_cols, row=3, bg=C["purple"])
        ws5.freeze_panes = "A4"
        MONEY5 = {ci for ci,c in enumerate(cdnr_cols,1) if any(k in c for k in MONEY_KW)}
        for ri,(_,row) in enumerate(cdnr_df.iterrows()):
            st    = str(row.get("Status",""))
            bg,fg = STATUS_CLR.get(st,(C["white"],"111111"))
            if not st: bg = C["ltpurple"] if ri%2==0 else C["white"]
            _data_row(ws5, 4+ri, list(row), bg=bg, fg=fg, money_cols=MONEY5)
        _set_col_widths(ws5, cdnr_cols, CW)
        # Legend
        leg_row = len(cdnr_df) + 6
        for lbl,clr in [("✅ Matched — Exact",C["ltgreen"]),
                         ("⚠️ Matched with Differences",C["ltamber"]),
                         ("❌ In 2B — Not in Books",C["ltred"]),
                         ("📘 In Books — Not in 2B",C["ltblue"])]:
            lc = ws5.cell(row=leg_row, column=1, value=lbl)
            lc.fill = PatternFill("solid",fgColor=clr)
            lc.font = Font(name="Calibri",size=9,bold=True)
            lc.alignment = Alignment(horizontal="left",vertical="center",indent=1)
            ws5.row_dimensions[leg_row].height = 16
            leg_row += 1

    buf = io.BytesIO(); wb.save(buf); buf.seek(0)
    return buf.getvalue()

def build_excel(df):
    cols_to_drop = ["Rev Charge", "ITC", "ITC Reason", "Match Method", "Match Tier", "GSTIN"]
    df = df.drop(columns=[c for c in cols_to_drop if c in df.columns], errors='ignore')
    wb = Workbook(); wb.remove(wb.active)
    thin = Side(style="thin", color="D0D0D0")
    bdr  = Border(left=thin, right=thin, top=thin, bottom=thin)
    SS   = {"MATCHED":("E2EFDA","1E4620"),"MATCHED WITH DIFF":("FFF2CC","7B4F00"),
            "IN 2B – NOT IN BOOKS":("FCE4D6","843C0C"),"IN BOOKS – NOT IN 2B":("DAEEF3","0D3D5E")}
    ws = wb.create_sheet("Reconciliation"); ws.sheet_properties.tabColor="1F3864"
    ws.merge_cells(f"A1:{get_column_letter(len(df.columns))}1")
    ws["A1"].value     = f"GST 2B vs Books — Reconciliation  |  {datetime.now().strftime('%d-%b-%Y %H:%M')}"
    ws["A1"].font      = Font(name="Calibri",bold=True,size=12,color="FFFFFF")
    ws["A1"].fill      = PatternFill("solid",fgColor="1F3864")
    ws["A1"].alignment = Alignment(horizontal="center",vertical="center")
    ws.row_dimensions[1].height = 26
    for ci, col in enumerate(df.columns,1):
        c=ws.cell(row=2,column=ci,value=col)
        c.font=Font(name="Calibri",bold=True,size=10,color="FFFFFF")
        c.fill=PatternFill("solid",fgColor="2E75B6")
        c.alignment=Alignment(horizontal="center",vertical="center",wrap_text=True)
        c.border=bdr
    ws.row_dimensions[2].height=22
    MONEY={c for c in df.columns if any(k in c for k in ["Taxable","IGST","CGST","SGST","Total Tax"])}
    for ri,(_, row) in enumerate(df.iterrows()):
        r=3+ri; bg,fg=SS.get(row.get("Status",""),("FFFFFF","111111"))
        for ci, val in enumerate(row,1):
            cn=df.columns[ci-1]; cell=ws.cell(row=r,column=ci,value=val)
            cell.fill=PatternFill("solid",fgColor=bg); cell.border=bdr
            cell.font=Font(name="Calibri",size=10,bold=(cn=="Status"),color=fg)
            if cn in MONEY:
                cell.number_format="##,##,##0.00"
                cell.alignment=Alignment(horizontal="right",vertical="center")
            else: cell.alignment=Alignment(horizontal="left",vertical="center")
    CW={"GSTIN":22,"Vendor":26,"Invoice No (2B)":18,"Invoice No (Books)":18,
        "Invoice Date (2B)":16,"Invoice Date (Books)":16,
        "Taxable (2B)":14,"Taxable (Books)":14,
        "IGST (2B)":12,"IGST (Books)":12,"CGST (2B)":12,"CGST (Books)":12,
        "SGST (2B)":12,"SGST (Books)":12,"Status":22,"Remarks":34}
    for ci, col in enumerate(df.columns,1):
        ws.column_dimensions[get_column_letter(ci)].width=CW.get(col,14)
    ws.freeze_panes="A3"

    ws2=wb.create_sheet("Summary"); ws2.sheet_properties.tabColor="375623"
    ws2.merge_cells("A1:B1")
    ws2["A1"].value=  "Reconciliation Summary"
    ws2["A1"].font=   Font(name="Calibri",bold=True,size=12,color="FFFFFF")
    ws2["A1"].fill=   PatternFill("solid",fgColor="1F3864")
    ws2["A1"].alignment=Alignment(horizontal="center",vertical="center")
    ws2.row_dimensions[1].height=26
    for ri,(lbl,cnt,clr) in enumerate([
        ("Total GSTR-2B Records", (df["Invoice No (2B)"]!="").sum(),"DAEEF3"),
        ("Total Books Records",   (df["Invoice No (Books)"]!="").sum(),"DAEEF3"),
        ("Matched — Exact",       (df["Status"]=="MATCHED").sum(),"E2EFDA"),
        ("Matched — With Diff",   (df["Status"]=="MATCHED WITH DIFF").sum(),"FFF2CC"),
        ("In 2B — Not in Books",  (df["Status"]=="IN 2B – NOT IN BOOKS").sum(),"FCE4D6"),
        ("In Books — Not in 2B",  (df["Status"]=="IN BOOKS – NOT IN 2B").sum(),"DAEEF3"),
    ]):
        r=ri+2; c1=ws2.cell(row=r,column=1,value=lbl); c2=ws2.cell(row=r,column=2,value=cnt)
        for c in (c1,c2):
            c.fill=PatternFill("solid",fgColor=clr); c.border=bdr; c.font=Font(name="Calibri",size=11)
        c1.alignment=Alignment(horizontal="left",vertical="center")
        c2.alignment=Alignment(horizontal="center",vertical="center")
        c2.font=Font(name="Calibri",size=11,bold=True); ws2.row_dimensions[r].height=20
    ws2.column_dimensions["A"].width=34; ws2.column_dimensions["B"].width=14
    buf=io.BytesIO(); wb.save(buf); buf.seek(0)
    return buf.getvalue()


